*** Test Cases ***
Ship Deck Scan
    ${deck}=    Set Variable    1
    ${max_decks}=    Set Variable    3
    WHILE    ${deck} <= ${max_decks}
        Log    Scanning Deck ${deck}
        ${compartment}=    Set Variable    1
        ${max_compartments}=    Set Variable    4
        WHILE    ${compartment} <= ${max_compartments}
            Log    ${SPACE}${SPACE}Compartment ${compartment}: OK
            ${compartment}=    Set Variable    ${compartment + 1}
        END
        ${deck}=    Set Variable    ${deck + 1}
    END
    Log    All decks scanned
